/** Nom de chaque langue dans sa propre langue, affiché dans le sélecteur. */
const LANGS: Record<string, { nom: string; textes: Record<string, string> }> = {
  fr: { nom: 'Français', textes: fr },
  en: { nom: 'English', textes: en },
};
let current = 'fr';
export const setLang = (l: string) => { if (LANGS[l]) current = l; };
export const langue = () => current;
/** Langues proposées dans le sélecteur : celles qui ont un dictionnaire. */
export const LANGUES = Object.entries(LANGS).map(([code, l]) => ({ code, nom: l.nom }));

export function t(key: string, vars?: Record<string, string>): string {
  const s = LANGS[current].textes[key] ?? fr[key] ?? key;
  return vars ? s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '') : s;
}

/** « pagne(s) » / « yard(s) » / « mètre(s) » avec accord au pluriel (pluriel dès que la quantité dépasse 1). */
export const uniteLabel = (u: 'pagne' | 'yard' | 'metre', q: number) => t('unite.' + u) + (q > 1 ? 's' : '');
